fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Since tol is strictly positive, we just check if the absolute difference is less than tol.
    // subtraction a - b as i16 to avoid overflow issues, then take absolute value for comparison.
    let diff = (a as i16) - (b as i16);
    diff.abs() < (tol as i16)
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Assumptions:
    // - a.len() == b.len() > 0
    // - tol > 0
    // For each index, apply is_close_i8 and collect the result.
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| is_close_i8(x, y, tol))
        .collect()
}